import{_ as d,o as e,c as a,a4 as r}from"./chunks/framework.BMj-uaUw.js";const p=JSON.parse('{"title":"12 周课程地图","description":"","frontmatter":{},"headers":[{"level":2,"title":"整体节奏","slug":"整体节奏","link":"#整体节奏","children":[]},{"level":2,"title":"逐周安排","slug":"逐周安排","link":"#逐周安排","children":[{"level":3,"title":"模块一 · 工程化认知与工具链（第 1 - 3 周）","slug":"模块一-·-工程化认知与工具链-第-1-3-周","link":"#模块一-·-工程化认知与工具链-第-1-3-周","children":[]},{"level":3,"title":"模块二 · Vue 3 核心基础（第 4 - 6 周）","slug":"模块二-·-vue-3-核心基础-第-4-6-周","link":"#模块二-·-vue-3-核心基础-第-4-6-周","children":[]},{"level":3,"title":"模块三 · 组件化开发（第 7 - 8 周）","slug":"模块三-·-组件化开发-第-7-8-周","link":"#模块三-·-组件化开发-第-7-8-周","children":[]},{"level":3,"title":"模块四 · 应用架构（第 9 - 10 周）","slug":"模块四-·-应用架构-第-9-10-周","link":"#模块四-·-应用架构-第-9-10-周","children":[]},{"level":3,"title":"模块五 · 综合项目实战（第 11 - 12 周）","slug":"模块五-·-综合项目实战-第-11-12-周","link":"#模块五-·-综合项目实战-第-11-12-周","children":[]},{"level":3,"title":"AI 协作主线（贯穿 12 周）","slug":"ai-协作主线-贯穿-12-周","link":"#ai-协作主线-贯穿-12-周","children":[]}]},{"level":2,"title":"项目驱动的时间线","slug":"项目驱动的时间线","link":"#项目驱动的时间线","children":[]},{"level":2,"title":"用户端放在哪里","slug":"用户端放在哪里","link":"#用户端放在哪里","children":[]},{"level":2,"title":"每个单元的四学时怎么用","slug":"每个单元的四学时怎么用","link":"#每个单元的四学时怎么用","children":[]},{"level":2,"title":"学完这门课，你会带走什么","slug":"学完这门课-你会带走什么","link":"#学完这门课-你会带走什么","children":[]},{"level":2,"title":"下一步","slug":"下一步","link":"#下一步","children":[]}],"relativePath":"guide/roadmap.md","filePath":"guide/roadmap.md","lastUpdated":1789500889000}'),n={name:"guide/roadmap.md"};function i(l,t,o,h,s,c){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="_12-周课程地图" tabindex="-1">12 周课程地图 <a class="header-anchor" href="#_12-周课程地图" aria-label="Permalink to &quot;12 周课程地图&quot;">​</a></h1><p>这一页给你整门课的推进节奏：<strong>每周讲什么、产出什么、什么算过关。</strong></p><p>看清楚这张图，你就不会在第 10 周才发现&quot;前面练习的东西和项目对不上&quot;。</p><h2 id="整体节奏" tabindex="-1">整体节奏 <a class="header-anchor" href="#整体节奏" aria-label="Permalink to &quot;整体节奏&quot;">​</a></h2><p>48 学时按 12 周 × 4 学时安排，每周一个单元，<strong>一个单元正好一次课</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模块一 工程化认知与工具链   ████████████  12 学时  第 1 - 3 周</span></span>
<span class="line"><span>模块二 Vue 3 核心基础        ████████████  12 学时  第 4 - 6 周</span></span>
<span class="line"><span>模块三 组件化开发            ████████      8 学时   第 7 - 8 周</span></span>
<span class="line"><span>模块四 应用架构              ████████      8 学时   第 9 - 10 周</span></span>
<span class="line"><span>模块五 综合项目实战          ████████      8 学时   第 11 - 12 周</span></span></code></pre></div><h2 id="逐周安排" tabindex="-1">逐周安排 <a class="header-anchor" href="#逐周安排" aria-label="Permalink to &quot;逐周安排&quot;">​</a></h2><h3 id="模块一-·-工程化认知与工具链-第-1-3-周" tabindex="-1">模块一 · 工程化认知与工具链（第 1 - 3 周） <a class="header-anchor" href="#模块一-·-工程化认知与工具链-第-1-3-周" aria-label="Permalink to &quot;模块一 · 工程化认知与工具链（第 1 - 3 周）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周次</th><th>单元</th><th>主要内容</th><th>课堂产出</th></tr></thead><tbody><tr><td>第 1 周</td><td>1 · 工程化认知与开发环境</td><td>前端发展脉络；工程化解决的六类问题；现代前端项目结构；学习路线与岗位方向；环境自检</td><td>环境自检报告、个人学习路线图</td></tr><tr><td>第 2 周</td><td>2 · Node 生态与构建工具</td><td>Node 与版本管理；npm 与 pnpm；<code>package.json</code> 逐字段；语义化版本与锁文件；依赖排查；Vite 两段式构建、环境变量与常用配置</td><td>依赖排查单、可复用的 <code>vite.config.js</code></td></tr><tr><td>第 3 周</td><td>3 · 工程规范与 Git 协作</td><td>ESLint 扁平配置；Prettier 与 ESLint 的职责划分；编辑器联动与提交钩子；ES Module 与目录组织；Git 分支模型与冲突解决；自动构建</td><td>带校验钩子的工程模板、首次合并请求</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">模块一验收（第 3 周）</p><p>在一台干净环境上，仅凭仓库里的说明文档与配置文件，把工程跑起来、改一行代码看到界面变化、 提交一次代码并触发自动构建。<strong>做到这三点，本模块过关。</strong></p></div><h3 id="模块二-·-vue-3-核心基础-第-4-6-周" tabindex="-1">模块二 · Vue 3 核心基础（第 4 - 6 周） <a class="header-anchor" href="#模块二-·-vue-3-核心基础-第-4-6-周" aria-label="Permalink to &quot;模块二 · Vue 3 核心基础（第 4 - 6 周）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周次</th><th>单元</th><th>主要内容</th><th>课堂产出</th></tr></thead><tbody><tr><td>第 4 周</td><td>4 · 模板语法与响应式基础</td><td>声明式渲染与命令式操作；插值表达式；属性绑定（类名与内联样式）；事件绑定；指令总览；<code>ref</code> 与 <code>reactive</code>；自动解包规则；响应式原理初探</td><td>个人名片页（含交互）</td></tr><tr><td>第 5 周</td><td>5 · 计算属性与渲染控制</td><td>计算属性的缓存机制；侦听器与深层侦听；条件渲染家族；列表渲染与键值选择；四态页面；列表的不可变操作</td><td>待办清单、可排序筛选的数据表格</td></tr><tr><td>第 6 周</td><td>6 · 用户交互与表单绑定</td><td>事件对象与传参；事件与按键修饰符；各类表单元素的绑定形态；表单修饰符；校验的两种思路；生命周期钩子；模板引用与副作用清理</td><td>多步预订表单、Markdown 编辑器</td></tr></tbody></table><p><strong>阶段小结（第 6 周）</strong>：到这一周，你应该能独立写出一个带交互和数据展示的页面， 并且能解释&quot;为什么数据变了界面会更新&quot;。</p><h3 id="模块三-·-组件化开发-第-7-8-周" tabindex="-1">模块三 · 组件化开发（第 7 - 8 周） <a class="header-anchor" href="#模块三-·-组件化开发-第-7-8-周" aria-label="Permalink to &quot;模块三 · 组件化开发（第 7 - 8 周）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周次</th><th>单元</th><th>主要内容</th><th>课堂产出</th></tr></thead><tbody><tr><td>第 7 周</td><td>7 · 组件基础与父子通信</td><td>单文件组件三段结构；拆分依据；属性声明与校验；单向数据流；事件声明与触发；组件双向绑定的本质</td><td>自研卡片组件、可自定义单元格的表格组件</td></tr><tr><td>第 8 周</td><td>8 · 组件进阶与逻辑复用</td><td>三种插槽；依赖注入与只读封装；内置组件（过渡、缓存、传送门）；组合式函数设计与实战；自定义指令</td><td>可复用弹窗与全局通知、自研组合式函数集</td></tr></tbody></table><h3 id="模块四-·-应用架构-第-9-10-周" tabindex="-1">模块四 · 应用架构（第 9 - 10 周） <a class="header-anchor" href="#模块四-·-应用架构-第-9-10-周" aria-label="Permalink to &quot;模块四 · 应用架构（第 9 - 10 周）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周次</th><th>单元</th><th>主要内容</th><th>课堂产出</th></tr></thead><tbody><tr><td>第 9 周</td><td>9 · 路由与登录鉴权</td><td>路由表与路由出口；动态参数与查询参数；嵌套路由；未匹配路由；编程式导航；路由守卫；鉴权链路与登录后回跳；路由懒加载</td><td>带鉴权的页面骨架</td></tr><tr><td>第 10 周</td><td>10 · Pinia 与数据请求层</td><td>何时需要全局状态；两种状态模块写法；解构保持响应性；跨模块调用；状态持久化；请求实例与拦截器；错误分层；接口文件组织</td><td>登录态状态模块、请求层封装</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">阶段性任务（第 10 周）</p><p><strong>把路由与状态接起来</strong>：未登录访问受限页面被拦下，登录后自动回到原地址； 退出登录后再次访问受限页面仍然被拦。这一条链走通，模块四过关。</p></div><h3 id="模块五-·-综合项目实战-第-11-12-周" tabindex="-1">模块五 · 综合项目实战（第 11 - 12 周） <a class="header-anchor" href="#模块五-·-综合项目实战-第-11-12-周" aria-label="Permalink to &quot;模块五 · 综合项目实战（第 11 - 12 周）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周次</th><th>单元</th><th>主要内容</th><th>课堂产出</th></tr></thead><tbody><tr><td>第 11 周</td><td>11 · 项目启动与核心业务实现</td><td>需求梳理与页面清单；接口约定；目录规划与工程初始化；布局骨架与嵌套路由；列表页标准做法；表单页标准做法</td><td>需求规格说明、可运行骨架、三个业务页面</td></tr><tr><td>第 12 周</td><td>12 · 联调、优化、部署与答辩</td><td>联调准备与问题定位；构建优化与代码分包；部署与刷新 404 处理；交付材料；项目答辩</td><td>线上可访问项目、交付文档与答辩材料</td></tr></tbody></table><h3 id="ai-协作主线-贯穿-12-周" tabindex="-1">AI 协作主线（贯穿 12 周） <a class="header-anchor" href="#ai-协作主线-贯穿-12-周" aria-label="Permalink to &quot;AI 协作主线（贯穿 12 周）&quot;">​</a></h3><p>AI 协作不额外占课时，位置固定在每个单元的正文之后、练习之前。12 周下来的焦点这样递进：</p><table tabindex="0"><thead><tr><th>周次</th><th>单元</th><th>AI 协作焦点</th><th>小节</th></tr></thead><tbody><tr><td>第 1 周</td><td>单元 1</td><td>用 AI 做技术调研与排错，学会核实它的结论</td><td><a href="/frontend-engineering-course/unit01/ai-collaboration.html">打开</a></td></tr><tr><td>第 2 周</td><td>单元 2</td><td>依赖与版本不要交给 AI 记，自己查一遍</td><td><a href="/frontend-engineering-course/unit02/ai-collaboration.html">打开</a></td></tr><tr><td>第 3 周</td><td>单元 3</td><td>起草 AGENTS.md，让 AI 按项目约定产出</td><td><a href="/frontend-engineering-course/unit03/ai-collaboration.html">打开</a></td></tr><tr><td>第 4 周</td><td>单元 4</td><td>识别 Vue 2 的旧写法，守住响应式</td><td><a href="/frontend-engineering-course/unit04/ai-collaboration.html">打开</a></td></tr><tr><td>第 5 周</td><td>单元 5</td><td>让 AI 补齐四种状态，检查 key 的选择</td><td><a href="/frontend-engineering-course/unit05/ai-collaboration.html">打开</a></td></tr><tr><td>第 6 周</td><td>单元 6</td><td>表单校验的边界，副作用要清干净</td><td><a href="/frontend-engineering-course/unit06/ai-collaboration.html">打开</a></td></tr><tr><td>第 7 周</td><td>单元 7</td><td>组件边界的判断，别违反单向数据流</td><td><a href="/frontend-engineering-course/unit07/ai-collaboration.html">打开</a></td></tr><tr><td>第 8 周</td><td>单元 8</td><td>状态放错位置的坑，组合式函数的清理</td><td><a href="/frontend-engineering-course/unit08/ai-collaboration.html">打开</a></td></tr><tr><td>第 9 周</td><td>单元 9</td><td>认清前端判断不是安全边界</td><td><a href="/frontend-engineering-course/unit09/ai-collaboration.html">打开</a></td></tr><tr><td>第 10 周</td><td>单元 10</td><td>接口约定最容易走偏：成功码与字段名</td><td><a href="/frontend-engineering-course/unit10/ai-collaboration.html">打开</a></td></tr><tr><td>第 11 周</td><td>单元 11</td><td>走一遍从规格到实现的完整流程</td><td><a href="/frontend-engineering-course/unit11/ai-collaboration.html">打开</a></td></tr><tr><td>第 12 周</td><td>单元 12</td><td>AI 给的优化建议要先验证再采纳</td><td><a href="/frontend-engineering-course/unit12/ai-collaboration.html">打开</a></td></tr></tbody></table><p>总的方法见 <a href="/frontend-engineering-course/guide/ai-coding.html">AI 编程：用之前先知道它的边界</a>， 项目阶段的做法见 <a href="/frontend-engineering-course/project/ai-collaboration.html">综合项目 · AI 协作规范</a>。</p><h2 id="项目驱动的时间线" tabindex="-1">项目驱动的时间线 <a class="header-anchor" href="#项目驱动的时间线" aria-label="Permalink to &quot;项目驱动的时间线&quot;">​</a></h2><p><strong>项目不是从第 11 周才开始的。</strong> 这是整门课最重要的安排。</p><p>如果等到最后两周才动手，8 学时的课内时间根本做不完一个完整项目。所以真实的时间线是这样：</p><table tabindex="0"><thead><tr><th>阶段</th><th>周次</th><th>项目侧的动作</th></tr></thead><tbody><tr><td>准备期</td><td>第 1 - 3 周</td><td>产出工程模板（构建配置、规范配置、目录结构），<strong>项目仓库由此创建</strong></td></tr><tr><td>学徒期</td><td>第 4 - 6 周</td><td>在项目仓库里做页面级练习（表格、表单、清单），暂不接入真实接口</td></tr><tr><td>成形期</td><td>第 7 - 8 周</td><td>把练习里的重复部分抽成组件与组合式函数，项目开始有自己的组件</td></tr><tr><td>联通期</td><td>第 9 - 10 周</td><td>接上路由与状态管理，接入真实接口，项目变成能点得通的应用</td></tr><tr><td>交付期</td><td>第 11 - 12 周</td><td>补齐业务模块、联调、优化、部署、写文档、答辩</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">请在第 3 周就把仓库建好</p><p>这不是建议，是硬要求。第 3 周产出工程模板时，直接用模板初始化项目仓库， 之后每个单元的课堂练习都在这个仓库里完成。<strong>到第 11 周才开始建仓库的同学，基本都来不及。</strong></p></div><h2 id="用户端放在哪里" tabindex="-1">用户端放在哪里 <a class="header-anchor" href="#用户端放在哪里" aria-label="Permalink to &quot;用户端放在哪里&quot;">​</a></h2><p>项目有第二个端：学生用手机报名的 <strong>uni-app 用户端</strong>。它<strong>不占用这 12 周的课时</strong>， 默认排在管理端跑通之后，作为课后延伸或选做内容。</p><table tabindex="0"><thead><tr><th>时机</th><th>做什么</th></tr></thead><tbody><tr><td>第 9 - 10 周之后</td><td>管理端的路由、请求层、登录态已经有了，用户端直接复用这套约定</td></tr><tr><td>第 11 - 12 周</td><td>想做两端一起交付的同学，可以在这一端补 5 个页面，答辩时一起演示</td></tr><tr><td>课程结束后</td><td>作为独立的学习材料，从“为什么是 uni-app”顺序读到“打包与发布”</td></tr></tbody></table><p>放在这个位置是有理由的：用户端的核心难点不在 Vue 语法，而在跨端框架的那些差异 —— 锁定的依赖版本、rpx 单位、页面栈层数、没有全局路由守卫、组件库换包名。这些差异 <strong>只有在你已经熟悉 Vue 工程化的前提下才讲得清</strong>。所以先管理端，后用户端。</p><p>入口：<a href="/frontend-engineering-course/mobile/">用户端 · uni-app 实战</a>。</p><h2 id="每个单元的四学时怎么用" tabindex="-1">每个单元的四学时怎么用 <a class="header-anchor" href="#每个单元的四学时怎么用" aria-label="Permalink to &quot;每个单元的四学时怎么用&quot;">​</a></h2><p>课内 4 小时的分配大致如下：</p><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问本单元知识点，确认示例都跑过</td></tr><tr><td>讲解</td><td>1.3 学时</td><td>只讲重点与容易踩的坑</td></tr><tr><td>现场任务</td><td>1.8 学时</td><td>做本单元实训任务，老师走动排错</td></tr><tr><td>复盘</td><td>0.6 学时</td><td>展示两三个同学的写法，对比不同解法</td></tr></tbody></table><p>也就是说，<strong>课内有近一半时间是留给你自己写的</strong>。这些时间不用来打字，就是浪费。</p><h2 id="学完这门课-你会带走什么" tabindex="-1">学完这门课，你会带走什么 <a class="header-anchor" href="#学完这门课-你会带走什么" aria-label="Permalink to &quot;学完这门课，你会带走什么&quot;">​</a></h2><p>不只是分数，还有三样可以放进简历的东西：</p><ol><li><strong>一套自己的工程模板</strong> —— 带构建配置、代码规范、提交钩子的前端工程，新项目直接拿来用。</li><li><strong>一个能点得通的项目</strong> —— 校园活动服务平台，有登录、有业务模块、有数据看板、有线上地址； 愿意做第二个端的，还能多一个能扫码打开的手机端。</li><li><strong>一套组件与组合式函数</strong> —— 列表页、表单页、弹窗、请求封装，换个业务还能复用。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想知道每周具体学什么、怎么学 → 直接进 <a href="/frontend-engineering-course/unit01/">单元 1</a></li><li>想先看项目长什么样 → <a href="/frontend-engineering-course/project/">综合项目总览</a></li><li>想知道手机端怎么做 → <a href="/frontend-engineering-course/mobile/">用户端 · uni-app 实战</a></li><li>环境还没装好 → <a href="/frontend-engineering-course/guide/environment.html">开发环境准备</a></li></ul>`,43)])])}const b=d(n,[["render",i]]);export{p as __pageData,b as default};
